SELECT COUNT(*)
FROM project_photo
WHERE image_id = #{imageId}

SELECT 
FROM project_photo p
WHERE p.image_id = #{imageId}

SELECT 
FROM project_photo p
WHERE p.photographer_user_id = #{photographerUserId}
