mapper.update:
UPDATE project_photo
SET note = #{note},
    watermark_position = #{watermarkPosition},
    watermark_visible = #{watermarkVisible},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND project_id = #{projectId}
  AND photographer_user_id = #{photographerUserId}

mapper.delete:
DELETE FROM project_photo
WHERE project_id = #{projectId}
  AND id = #{photoId}
